import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { Bot, Plus, Trash2, Clock, Copy } from 'lucide-react'
import { getGlobalAgents, deleteGlobalAgent, updateGlobalAgent } from '../lib/api'
import { useApi } from '../hooks/useApi'

export default function GlobalAgents() {
  const { data: agents, loading, refetch } = useApi(getGlobalAgents)
  const navigate = useNavigate()
  const [creating, setCreating] = useState(false)
  const [newName, setNewName] = useState('')

  const handleCreate = async () => {
    if (!newName.trim()) return
    const slug = newName.trim().toLowerCase().replace(/\s+/g, '-')
    const template = `---
name: ${newName.trim()}
description: ""
model: ""
---

# ${newName.trim()}

Write your agent instructions here.
`
    await updateGlobalAgent(slug, template)
    setCreating(false)
    setNewName('')
    navigate(`/global/agents/${slug}`)
  }

  const handleDelete = async (name: string) => {
    if (!confirm(`Delete agent "${name}"?`)) return
    await deleteGlobalAgent(name)
    refetch()
  }

  if (loading) return <PageLoader />

  return (
    <div className="p-8 max-w-5xl">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <Bot className="w-6 h-6 text-purple" />
            Global Agents
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            Agents available across all projects
          </p>
        </div>
        <button
          onClick={() => setCreating(true)}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
        >
          <Plus className="w-4 h-4" />
          New Agent
        </button>
      </div>

      {/* Create modal */}
      {creating && (
        <div className="mb-6 bg-surface border border-border rounded-xl p-5">
          <p className="text-sm font-medium mb-3">Create New Agent</p>
          <div className="flex gap-3">
            <input
              type="text"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="Agent name..."
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && handleCreate()}
            />
            <button
              onClick={handleCreate}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
            >
              Create
            </button>
            <button
              onClick={() => {
                setCreating(false)
                setNewName('')
              }}
              className="px-4 py-2 text-sm text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* Agent list */}
      {!agents || agents.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <Bot className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">No global agents yet</p>
          <p className="text-text-muted text-sm mt-1">
            Create agents that are available across all your projects
          </p>
        </div>
      ) : (
        <div className="space-y-3">
          {agents.map((agent) => (
            <Link
              key={agent.filename}
              to={`/global/agents/${agent.filename}`}
              className="group flex items-center justify-between bg-surface border border-border rounded-xl p-5 hover:border-accent/40 transition-all"
            >
              <div className="flex items-center gap-4">
                <div className="p-2.5 rounded-lg bg-purple-muted">
                  <Bot className="w-5 h-5 text-purple" />
                </div>
                <div>
                  <h3 className="font-semibold text-[15px] group-hover:text-accent-hover transition-colors">
                    {agent.name}
                  </h3>
                  {agent.description && (
                    <p className="text-sm text-text-secondary mt-0.5">{agent.description}</p>
                  )}
                  <div className="flex items-center gap-3 mt-2">
                    {agent.model && (
                      <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-md font-mono">
                        {agent.model}
                      </span>
                    )}
                    <span className="flex items-center gap-1 text-xs text-text-muted">
                      <Clock className="w-3 h-3" />
                      {new Date(agent.updatedAt).toLocaleDateString()}
                    </span>
                  </div>
                </div>
              </div>
              <button
                onClick={(e) => {
                  e.preventDefault()
                  e.stopPropagation()
                  handleDelete(agent.filename)
                }}
                className="p-2 rounded-lg text-text-muted hover:text-red hover:bg-red-muted transition-colors opacity-0 group-hover:opacity-100"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </Link>
          ))}
        </div>
      )}
    </div>
  )
}

function PageLoader() {
  return (
    <div className="p-8 flex items-center justify-center h-64">
      <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

