import { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { Save, ArrowLeft, RotateCcw, Bot } from 'lucide-react'
import {
  getGlobalAgent,
  updateGlobalAgent,
  getProjectAgent,
  updateProjectAgent,
} from '../lib/api'

interface Props {
  scope: 'global' | 'project'
}

export default function AgentEditor({ scope }: Props) {
  const { name, projectId } = useParams()
  const navigate = useNavigate()
  const [content, setContent] = useState('')
  const [originalContent, setOriginalContent] = useState('')
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      try {
        const agent =
          scope === 'global'
            ? await getGlobalAgent(name!)
            : await getProjectAgent(projectId!, name!)
        setContent(agent.raw)
        setOriginalContent(agent.raw)
      } catch {
        setContent('')
        setOriginalContent('')
      }
      setLoading(false)
    }
    load()
  }, [name, projectId, scope])

  const handleSave = async () => {
    setSaving(true)
    try {
      if (scope === 'global') {
        await updateGlobalAgent(name!, content)
      } else {
        await updateProjectAgent(projectId!, name!, content)
      }
      setOriginalContent(content)
      setDirty(false)
    } finally {
      setSaving(false)
    }
  }

  const backPath = scope === 'global' ? '/global/agents' : `/projects/${projectId}`

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="p-8 max-w-5xl h-screen flex flex-col">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate(backPath)}
            className="p-2 rounded-lg text-text-muted hover:text-text hover:bg-surface-2 transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div>
            <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
              <Bot className="w-6 h-6 text-purple" />
              {name}
            </h1>
            <p className="text-text-secondary text-sm mt-0.5">
              {scope === 'global' ? 'Global agent' : 'Project agent'} — Edit raw markdown
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {dirty && (
            <button
              onClick={() => {
                setContent(originalContent)
                setDirty(false)
              }}
              className="flex items-center gap-2 px-3 py-2 text-sm text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
            >
              <RotateCcw className="w-4 h-4" />
              Reset
            </button>
          )}
          <button
            onClick={handleSave}
            disabled={!dirty || saving}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
          >
            <Save className="w-4 h-4" />
            {saving ? 'Saving...' : 'Save'}
          </button>
        </div>
      </div>

      <div className="flex-1 min-h-0">
        <textarea
          value={content}
          onChange={(e) => {
            setContent(e.target.value)
            setDirty(true)
          }}
          className="w-full h-full bg-surface border border-border rounded-xl p-5 font-mono text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors"
          placeholder="---&#10;name: Agent Name&#10;description: What this agent does&#10;model: sonnet&#10;---&#10;&#10;Agent instructions..."
          spellCheck={false}
        />
      </div>
    </div>
  )
}

