}

function ClaudeMdTab({ projectId }: { projectId: string }) {
  const { data, loading } = useApi(() => getProjectClaudeMd(projectId), [projectId])
  const [content, setContent] = useState('')
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)

  useState(() => {
    if (data) {
      setContent(data.content)
    }
  })

  // Sync when data loads
  if (data && !dirty && content !== data.content) {
    setContent(data.content)
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      await updateProjectClaudeMd(projectId, content)
      setDirty(false)
    } finally {
      setSaving(false)
    }
  }

  if (loading) return <TabLoader />

  return (
    <div className="flex flex-col" style={{ height: 'calc(100vh - 240px)' }}>
      <div className="flex items-center justify-end mb-4 gap-2">
        {dirty && (
          <button
            onClick={() => {
              if (data) setContent(data.content)
              setDirty(false)
            }}
            className="flex items-center gap-2 px-3 py-2 text-sm text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
          >
            <RotateCcw className="w-4 h-4" />
            Reset
          </button>
        )}
        <button
          onClick={handleSave}
          disabled={!dirty || saving}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          <Save className="w-4 h-4" />
          {saving ? 'Saving...' : 'Save'}
        </button>
      </div>
      <textarea
        value={content}
        onChange={(e) => {
          setContent(e.target.value)
          setDirty(true)
        }}
        className="flex-1 w-full bg-surface border border-border rounded-xl p-5 font-mono text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors"
        spellCheck={false}
        placeholder="# Project CLAUDE.md&#10;&#10;Write project-specific instructions here..."
      />
    </div>
  )
}

function AgentsTab({
  agents,
  projectId,
  refetch,
}: {
  agents: { filename: string; name: string; description: string; model: string; updatedAt: string }[]
  projectId: string
  refetch: () => void
}) {
  const navigate = useNavigate()
  const [creating, setCreating] = useState(false)
  const [newName, setNewName] = useState('')

  const handleCreate = async () => {
    if (!newName.trim()) return
    const slug = newName.trim().toLowerCase().replace(/\s+/g, '-')
    const template = `---\nname: ${newName.trim()}\ndescription: ""\nmodel: ""\n---\n\n# ${newName.trim()}\n\nWrite your agent instructions here.\n`
    await updateProjectAgent(projectId, slug, template)
    setCreating(false)
    setNewName('')
    navigate(`/projects/${projectId}/agents/${slug}`)
  }

  const handleDelete = async (name: string) => {
    if (!confirm(`Delete agent "${name}"?`)) return
    await deleteProjectAgent(projectId, name)
    refetch()
  }

  return (
    <div>
      <div className="flex justify-end mb-4">
        <button
          onClick={() => setCreating(true)}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
        >
          <Plus className="w-4 h-4" />
          New Agent
        </button>
      </div>

      {creating && (
        <div className="mb-4 bg-surface border border-border rounded-xl p-5">
          <p className="text-sm font-medium mb-3">Create New Agent</p>
          <div className="flex gap-3">
            <input
              type="text"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="Agent name..."
              className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm focus:outline-none focus:border-accent/50"
              autoFocus
              onKeyDown={(e) => e.key === 'Enter' && handleCreate()}
            />
            <button
              onClick={handleCreate}
              className="px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
            >
              Create
            </button>
            <button
              onClick={() => {
                setCreating(false)
                setNewName('')
              }}
              className="px-4 py-2 text-sm text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {agents.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <Bot className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">No agents in this project</p>
        </div>
      ) : (
        <div className="space-y-3">
          {agents.map((agent) => (
            <Link
              key={agent.filename}
              to={`/projects/${projectId}/agents/${agent.filename}`}
              className="group flex items-center justify-between bg-surface border border-border rounded-xl p-5 hover:border-accent/40 transition-all"
            >
              <div className="flex items-center gap-4">
                <div className="p-2.5 rounded-lg bg-purple-muted">
                  <Bot className="w-5 h-5 text-purple" />
                </div>
                <div>
                  <h3 className="font-semibold text-[15px] group-hover:text-accent-hover transition-colors">
                    {agent.name}
                  </h3>
                  {agent.description && (
                    <p className="text-sm text-text-secondary mt-0.5">{agent.description}</p>
                  )}
                  <div className="flex items-center gap-3 mt-2">
                    {agent.model && (
                      <span className="text-xs text-text-muted bg-surface-2 px-2 py-0.5 rounded-md font-mono">
                        {agent.model}
                      </span>
                    )}
                    <span className="flex items-center gap-1 text-xs text-text-muted">
                      <Clock className="w-3 h-3" />
                      {new Date(agent.updatedAt).toLocaleDateString()}
                    </span>
                  </div>
                </div>
              </div>
              <button
                onClick={(e) => {
                  e.preventDefault()
                  e.stopPropagation()
                  handleDelete(agent.filename)
                }}
                className="p-2 rounded-lg text-text-muted hover:text-red hover:bg-red-muted transition-colors opacity-0 group-hover:opacity-100"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </Link>
          ))}
        </div>
      )}
    </div>
  )
}

function CommandsTab({ commands }: { commands: { name: string; content: string }[] }) {
  const [expanded, setExpanded] = useState<string | null>(null)

  if (commands.length === 0) {
    return (
      <div className="bg-surface rounded-xl border border-border p-12 text-center">
        <Terminal className="w-10 h-10 text-text-muted mx-auto mb-3" />
        <p className="text-text-secondary font-medium">No commands in this project</p>
        <p className="text-text-muted text-sm mt-1">
          Add .md files to .claude/commands/ to create slash commands
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-3">
      {commands.map((cmd) => (
        <div key={cmd.name} className="bg-surface border border-border rounded-xl overflow-hidden">
          <button
            onClick={() => setExpanded(expanded === cmd.name ? null : cmd.name)}
            className="w-full flex items-center gap-3 p-4 text-left hover:bg-surface-2 transition-colors"
          >
            <Terminal className="w-4 h-4 text-amber shrink-0" />
            <span className="font-medium text-sm font-mono">/{cmd.name}</span>
          </button>
          {expanded === cmd.name && (
            <div className="border-t border-border p-4 bg-surface-2">
              <pre className="text-sm text-text-secondary font-mono whitespace-pre-wrap">
                {cmd.content}
              </pre>
            </div>
          )}
        </div>
      ))}
    </div>
  )
}

function RulesTab({ rules }: { rules: { name: string; content: string }[] }) {
  const [expanded, setExpanded] = useState<string | null>(null)

  if (rules.length === 0) {
    return (
      <div className="bg-surface rounded-xl border border-border p-12 text-center">
        <ShieldCheck className="w-10 h-10 text-text-muted mx-auto mb-3" />
        <p className="text-text-secondary font-medium">No rules in this project</p>
        <p className="text-text-muted text-sm mt-1">
          Add .md files to .claude/rules/ to define project rules
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-3">
      {rules.map((rule) => (
        <div key={rule.name} className="bg-surface border border-border rounded-xl overflow-hidden">
          <button
            onClick={() => setExpanded(expanded === rule.name ? null : rule.name)}
            className="w-full flex items-center gap-3 p-4 text-left hover:bg-surface-2 transition-colors"
          >
            <ShieldCheck className="w-4 h-4 text-text-secondary shrink-0" />
            <span className="font-medium text-sm">{rule.name}</span>
          </button>
          {expanded === rule.name && (
            <div className="border-t border-border p-4 bg-surface-2">
              <pre className="text-sm text-text-secondary font-mono whitespace-pre-wrap">
                {rule.content}
              </pre>
            </div>
          )}
        </div>
      ))}
    </div>
  )
}

function TabLoader() {
  return (
    <div className="flex items-center justify-center h-32">
      <div className="w-5 h-5 border-2 border-accent border-t-transparent rounded-full animate-spin" />
    </div>
  )
}

