import { useState, useEffect } from 'react'
import { Settings, Plus, Trash2, Save, FolderOpen, Info } from 'lucide-react'
import { getConfig, updateProjectDirs } from '../lib/api'
import { useApi } from '../hooks/useApi'

interface Props {
  onSave: () => void
}

export default function SettingsPage({ onSave }: Props) {
  const { data: config, loading } = useApi(getConfig)
  const [dirs, setDirs] = useState<string[]>([])
  const [newDir, setNewDir] = useState('')
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)

  useEffect(() => {
    if (config) {
      setDirs(config.projectDirs || [])
      setDirty(false)
    }
  }, [config])

  const handleAdd = () => {
    if (!newDir.trim()) return
    const dir = newDir.trim()
    if (!dirs.includes(dir)) {
      setDirs([...dirs, dir])
      setDirty(true)
    }
    setNewDir('')
  }

  const handleRemove = (index: number) => {
    setDirs(dirs.filter((_, i) => i !== index))
    setDirty(true)
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      await updateProjectDirs(dirs)
      setDirty(false)
      onSave()
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="p-8 max-w-3xl">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight flex items-center gap-3">
            <Settings className="w-6 h-6 text-text-secondary" />
            Settings
          </h1>
          <p className="text-text-secondary text-sm mt-1">
            Configure Claude Hub
          </p>
        </div>
        <button
          onClick={handleSave}
          disabled={!dirty || saving}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
        >
          <Save className="w-4 h-4" />
          {saving ? 'Saving...' : 'Save'}
        </button>
      </div>

      {/* Info */}
      <div className="bg-accent-muted border border-accent/20 rounded-xl p-4 mb-6 flex items-start gap-3">
        <Info className="w-5 h-5 text-accent shrink-0 mt-0.5" />
        <div className="text-sm text-accent-hover">
          <p className="font-medium mb-1">How project discovery works</p>
          <p className="text-text-secondary">
            Add parent directories below. Claude Hub scans each directory for subdirectories
            containing <code className="text-accent font-mono text-xs">.claude/</code>,{' '}
            <code className="text-accent font-mono text-xs">CLAUDE.md</code>, or{' '}
            <code className="text-accent font-mono text-xs">package.json</code>.
          </p>
        </div>
      </div>

      {/* Claude directory info */}
      <div className="bg-surface border border-border rounded-xl p-5 mb-6">
        <div className="flex items-center gap-3 mb-3">
          <FolderOpen className="w-5 h-5 text-text-muted" />
          <div>
            <p className="text-sm font-medium">Claude Directory</p>
            <p className="text-xs text-text-muted font-mono">{config?.claudeDir}</p>
          </div>
          <span
            className={`ml-auto text-xs px-2 py-1 rounded-md ${
              config?.claudeDirExists
                ? 'bg-green-muted text-green'
                : 'bg-red-muted text-red'
            }`}
          >
            {config?.claudeDirExists ? 'Found' : 'Not found'}
          </span>
        </div>
      </div>

      {/* Project Directories */}
      <div className="bg-surface border border-border rounded-xl p-5">
        <h2 className="text-base font-semibold mb-4">Project Directories</h2>

        {/* Add new */}
        <div className="flex gap-3 mb-4">
          <input
            type="text"
            value={newDir}
            onChange={(e) => setNewDir(e.target.value)}
            placeholder="~/Projects or /absolute/path..."
            className="flex-1 bg-surface-2 border border-border rounded-lg px-3 py-2.5 text-sm font-mono focus:outline-none focus:border-accent/50"
            onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
          />
          <button
            onClick={handleAdd}
            className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-surface-2 text-text-secondary rounded-lg hover:bg-surface-3 hover:text-text transition-colors border border-border"
          >
            <Plus className="w-4 h-4" />
            Add
          </button>
        </div>

        {/* List */}
        {dirs.length === 0 ? (
          <p className="text-sm text-text-muted py-4 text-center">
            No directories configured. Add a directory above to start scanning for projects.
          </p>
        ) : (
          <div className="space-y-2">
            {dirs.map((dir, i) => (
              <div
                key={i}
                className="flex items-center justify-between bg-surface-2 rounded-lg px-4 py-3"
              >
                <span className="text-sm font-mono text-text-secondary">{dir}</span>
                <button
                  onClick={() => handleRemove(i)}
                  className="p-1.5 rounded-md text-text-muted hover:text-red hover:bg-red-muted transition-colors"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

