const express = require('express');
const fs = require('fs');
const path = require('path');
const os = require('os');
const matter = require('gray-matter');

const app = express();
app.use(express.json({ limit: '5mb' }));
// Serve built React frontend, fallback to legacy public/
const distPath = path.join(__dirname, '..', 'public-dist');
const legacyPath = path.join(__dirname, '..', 'public');
const staticPath = fs.existsSync(distPath) ? distPath : legacyPath;
app.use(express.static(staticPath));

const HOME = os.homedir();
const CLAUDE_DIR = path.join(HOME, '.claude');
const CONFIG_PATH = path.join(__dirname, '..', 'config.json');

// --- Config Management ---
function loadConfig() {
  try {
    if (fs.existsSync(CONFIG_PATH)) {
      return JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf-8'));
    }
  } catch {}
  return { projectDirs: [] };
}

function saveConfig(config) {
  fs.writeFileSync(CONFIG_PATH, JSON.stringify(config, null, 2));
}

// --- Helpers ---
function ensureDir(dir) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

function readFileSafe(filePath) {
  try {
    if (fs.existsSync(filePath)) return fs.readFileSync(filePath, 'utf-8');
  } catch {}
  return null;
}

function parseAgent(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    const { data, content: body } = matter(content);
    const stats = fs.statSync(filePath);
    return {
      filename: path.basename(filePath, '.md'),
      path: filePath,
      frontmatter: data,
      name: data.name || path.basename(filePath, '.md'),
      description: data.description || '',
      model: data.model || '',
      tools: data.tools || '',
      body: body.trim(),
      raw: content,
      updatedAt: stats.mtime.toISOString(),
    };
  } catch (e) {
    return null;
  }
}

function listAgents(dir) {
  try {
    if (!fs.existsSync(dir)) return [];
    return fs.readdirSync(dir)
      .filter(f => f.endsWith('.md'))
      .map(f => parseAgent(path.join(dir, f)))
      .filter(Boolean);
  } catch {
    return [];
  }
}

function discoverProjects(dirs) {
  const projects = [];
  for (const dir of dirs) {
    const resolved = dir.replace(/^~/, HOME);
    if (!fs.existsSync(resolved)) continue;
    try {
      const entries = fs.readdirSync(resolved, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) continue;
        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
        const projectPath = path.join(resolved, entry.name);
        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
          const commands = [];
          const cmdDir = path.join(projectPath, '.claude', 'commands');
          try {
            if (fs.existsSync(cmdDir)) {
              commands.push(...fs.readdirSync(cmdDir).filter(f => f.endsWith('.md')));
            }
          } catch {}
          const rules = [];
          const rulesDir = path.join(projectPath, '.claude', 'rules');
          try {
            if (fs.existsSync(rulesDir)) {
              rules.push(...fs.readdirSync(rulesDir).filter(f => f.endsWith('.md')));
            }
          } catch {}
          projects.push({
            id: Buffer.from(projectPath).toString('base64url'),
            name: entry.name,
            path: projectPath,
            displayPath: projectPath.replace(HOME, '~'),
            hasClaudeDir,
            hasClaudeMd,
            agentCount: agents.length,
            agents,
            commands: commands.map(c => c.replace('.md', '')),
            rules: rules.map(r => r.replace('.md', '')),
          });
        }
      }
    } catch {}
  }
  return projects;
}

// --- API Routes ---

// Config
app.get('/api/config', (req, res) => {
  const config = loadConfig();
  res.json({
    claudeDir: CLAUDE_DIR,
    claudeDirExists: fs.existsSync(CLAUDE_DIR),
    home: HOME,
    ...config,
  });
});

app.post('/api/config/project-dirs', (req, res) => {
  const { dirs } = req.body;
  const config = loadConfig();
  config.projectDirs = dirs;
  saveConfig(config);
  res.json({ ok: true });
});

// Global CLAUDE.md
app.get('/api/global/claude-md', (req, res) => {
  const content = readFileSafe(path.join(CLAUDE_DIR, 'CLAUDE.md'));
  res.json({ content: content || '', exists: content !== null });
});

app.put('/api/global/claude-md', (req, res) => {
  ensureDir(CLAUDE_DIR);
  fs.writeFileSync(path.join(CLAUDE_DIR, 'CLAUDE.md'), req.body.content);
  res.json({ ok: true });
});

// Global Agents
app.get('/api/global/agents', (req, res) => {
  const agents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  res.json(agents);
});

app.get('/api/global/agents/:name', (req, res) => {
  const agent = parseAgent(path.join(CLAUDE_DIR, 'agents', req.params.name + '.md'));
  if (!agent) return res.status(404).json({ error: 'Not found' });
  res.json(agent);
});

app.put('/api/global/agents/:name', (req, res) => {
  const dir = path.join(CLAUDE_DIR, 'agents');
  ensureDir(dir);
  const filePath = path.join(dir, req.params.name + '.md');
  fs.writeFileSync(filePath, req.body.content);
  res.json({ ok: true, agent: parseAgent(filePath) });
});

app.delete('/api/global/agents/:name', (req, res) => {
  const filePath = path.join(CLAUDE_DIR, 'agents', req.params.name + '.md');
  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  res.json({ ok: true });
});

// Projects
app.get('/api/projects', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  res.json(projects);
});

// Project CLAUDE.md
app.get('/api/projects/:id/claude-md', (req, res) => {
  const projectPath = Buffer.from(req.params.id, 'base64url').toString();
  const content = readFileSafe(path.join(projectPath, 'CLAUDE.md'));
  res.json({ content: content || '', exists: content !== null, path: projectPath });
});

app.put('/api/projects/:id/claude-md', (req, res) => {
  const projectPath = Buffer.from(req.params.id, 'base64url').toString();
  fs.writeFileSync(path.join(projectPath, 'CLAUDE.md'), req.body.content);
  res.json({ ok: true });
});

// Project Agents
app.get('/api/projects/:id/agents', (req, res) => {
  const projectPath = Buffer.from(req.params.id, 'base64url').toString();
  const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
  res.json(agents);
});

app.get('/api/projects/:id/agents/:name', (req, res) => {
  const projectPath = Buffer.from(req.params.id, 'base64url').toString();
  const agent = parseAgent(path.join(projectPath, '.claude', 'agents', req.params.name + '.md'));
  if (!agent) return res.status(404).json({ error: 'Not found' });
  res.json(agent);
});

app.put('/api/projects/:id/agents/:name', (req, res) => {
  const projectPath = Buffer.from(req.params.id, 'base64url').toString();
  const dir = path.join(projectPath, '.claude', 'agents');
  ensureDir(dir);
  const filePath = path.join(dir, req.params.name + '.md');
  fs.writeFileSync(filePath, req.body.content);
  res.json({ ok: true, agent: parseAgent(filePath) });
});

app.delete('/api/projects/:id/agents/:name', (req, res) => {
  const projectPath = Buffer.from(req.params.id, 'base64url').toString();
  const filePath = path.join(projectPath, '.claude', 'agents', req.params.name + '.md');
  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
  res.json({ ok: true });
});

// Project Commands
app.get('/api/projects/:id/commands', (req, res) => {
  const projectPath = Buffer.from(req.params.id, 'base64url').toString();
  const cmdDir = path.join(projectPath, '.claude', 'commands');
  try {
    if (!fs.existsSync(cmdDir)) return res.json([]);
    const commands = fs.readdirSync(cmdDir)
      .filter(f => f.endsWith('.md'))
      .map(f => {
        const content = readFileSafe(path.join(cmdDir, f));
        return { name: f.replace('.md', ''), content, path: path.join(cmdDir, f) };
      });
    res.json(commands);
  } catch {
    res.json([]);
  }
});

app.put('/api/projects/:id/commands/:name', (req, res) => {
  const projectPath = Buffer.from(req.params.id, 'base64url').toString();
  const dir = path.join(projectPath, '.claude', 'commands');
  ensureDir(dir);
  fs.writeFileSync(path.join(dir, req.params.name + '.md'), req.body.content);
  res.json({ ok: true });
});

// Project Rules
app.get('/api/projects/:id/rules', (req, res) => {
  const projectPath = Buffer.from(req.params.id, 'base64url').toString();
  const rulesDir = path.join(projectPath, '.claude', 'rules');
  try {
    if (!fs.existsSync(rulesDir)) return res.json([]);
    const rules = fs.readdirSync(rulesDir)
      .filter(f => f.endsWith('.md'))
      .map(f => {
        const content = readFileSafe(path.join(rulesDir, f));
        return { name: f.replace('.md', ''), content, path: path.join(rulesDir, f) };
      });
    res.json(rules);
  } catch {
    res.json([]);
  }
});

// --- Directory Browser ---
app.get('/api/browse', (req, res) => {
  let targetPath = (req.query.path || HOME).replace(/^~/, HOME);
  // Resolve to absolute
  targetPath = path.resolve(targetPath);

  try {
    if (!fs.existsSync(targetPath)) {
      return res.status(404).json({ error: 'Path not found' });
    }
    const stat = fs.statSync(targetPath);
    if (!stat.isDirectory()) {
      return res.status(400).json({ error: 'Not a directory' });
    }

    const entries = fs.readdirSync(targetPath, { withFileTypes: true });
    const dirs = entries
      .filter(e => e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules' && e.name !== '__pycache__')
      .map(e => ({
        name: e.name,
        path: path.join(targetPath, e.name),
        displayPath: path.join(targetPath, e.name).replace(HOME, '~'),
        hasProjects: false, // will check below
      }))
      .sort((a, b) => a.name.localeCompare(b.name));

    // Quick check: does each dir contain recognizable projects?
    for (const dir of dirs) {
      try {
        const sub = fs.readdirSync(dir.path, { withFileTypes: true });
        dir.hasProjects = sub.some(s =>
          s.isDirectory() && (
            fs.existsSync(path.join(dir.path, s.name, '.claude')) ||
            fs.existsSync(path.join(dir.path, s.name, 'CLAUDE.md')) ||
            fs.existsSync(path.join(dir.path, s.name, 'package.json')) ||
            fs.existsSync(path.join(dir.path, s.name, 'pubspec.yaml'))
          )
        );
      } catch {}
    }

    // Breadcrumb parts
    const parts = targetPath.split(path.sep).filter(Boolean);
    const breadcrumbs = parts.map((part, i) => ({
      name: i === 0 && targetPath.startsWith(HOME) ? '~' : part,
      path: path.sep + parts.slice(0, i + 1).join(path.sep),
    }));

    // If we're in home dir, replace first crumb
    if (targetPath.startsWith(HOME)) {
      const homeIndex = HOME.split(path.sep).filter(Boolean).length - 1;
      breadcrumbs.splice(0, homeIndex + 1, { name: '~', path: HOME });
    }

    res.json({
      current: targetPath,
      displayPath: targetPath.replace(HOME, '~'),
      parent: path.dirname(targetPath) !== targetPath ? path.dirname(targetPath) : null,
      breadcrumbs,
      directories: dirs,
    });
  } catch (e) {
    res.status(500).json({ error: 'Cannot read directory' });
  }
});

// --- Unified endpoints (all agents/commands/rules across all projects + global) ---

app.get('/api/unified/agents', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const results = [];

  // Global agents
  const globalAgents = listAgents(path.join(CLAUDE_DIR, 'agents'));
  for (const agent of globalAgents) {
    results.push({ ...agent, scope: 'global', scopeLabel: 'Global', projectId: null, projectName: null });
  }

  // Per-project agents
  for (const project of projects) {
    for (const agent of project.agents) {
      results.push({ ...agent, scope: 'project', scopeLabel: project.name, projectId: project.id, projectName: project.name });
    }
  }

  results.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  res.json(results);
});

app.get('/api/unified/commands', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const results = [];

  for (const project of projects) {
    const cmdDir = path.join(project.path, '.claude', 'commands');
    try {
      if (!fs.existsSync(cmdDir)) continue;
      const files = fs.readdirSync(cmdDir).filter(f => f.endsWith('.md'));
      for (const f of files) {
        const content = readFileSafe(path.join(cmdDir, f));
        const stats = fs.statSync(path.join(cmdDir, f));
        results.push({
          name: f.replace('.md', ''),
          content,
          path: path.join(cmdDir, f),
          projectId: project.id,
          projectName: project.name,
          updatedAt: stats.mtime.toISOString(),
        });
      }
    } catch {}
  }

  results.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  res.json(results);
});

app.get('/api/unified/rules', (req, res) => {
  const config = loadConfig();
  const projects = discoverProjects(config.projectDirs);
  const results = [];

  for (const project of projects) {
    const rulesDir = path.join(project.path, '.claude', 'rules');
    try {
      if (!fs.existsSync(rulesDir)) continue;
      const files = fs.readdirSync(rulesDir).filter(f => f.endsWith('.md'));
      for (const f of files) {
        const content = readFileSafe(path.join(rulesDir, f));
        const stats = fs.statSync(path.join(rulesDir, f));
        results.push({
          name: f.replace('.md', ''),
          content,
          path: path.join(rulesDir, f),
          projectId: project.id,
          projectName: project.name,
          updatedAt: stats.mtime.toISOString(),
        });
      }
    } catch {}
  }

  results.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
  res.json(results);
});

// Move agent (copy + delete source)
app.post('/api/move-agent', (req, res) => {
  const { from, to, agentName } = req.body;
  let srcPath, destDir;
  if (from === 'global') {
    srcPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
  } else {
    const fromPath = Buffer.from(from, 'base64url').toString();
    srcPath = path.join(fromPath, '.claude', 'agents', agentName + '.md');
  }
  if (to === 'global') {
    destDir = path.join(CLAUDE_DIR, 'agents');
  } else {
    const toPath = Buffer.from(to, 'base64url').toString();
    destDir = path.join(toPath, '.claude', 'agents');
  }
  ensureDir(destDir);
  const content = readFileSafe(srcPath);
  if (!content) return res.status(404).json({ error: 'Source agent not found' });
  fs.writeFileSync(path.join(destDir, agentName + '.md'), content);
  if (fs.existsSync(srcPath)) fs.unlinkSync(srcPath);
  res.json({ ok: true });
});

// Global settings
app.get('/api/global/settings', (req, res) => {
  const content = readFileSafe(path.join(CLAUDE_DIR, 'settings.json'));
  try {
    res.json(content ? JSON.parse(content) : {});
  } catch {
    res.json({});
  }
});

// Copy agent between scopes
app.post('/api/copy-agent', (req, res) => {
  const { from, to, agentName } = req.body;
  let srcPath, destDir;
  if (from === 'global') {
    srcPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
  } else {
    const fromPath = Buffer.from(from, 'base64url').toString();
    srcPath = path.join(fromPath, '.claude', 'agents', agentName + '.md');
  }
  if (to === 'global') {
    destDir = path.join(CLAUDE_DIR, 'agents');
  } else {
    const toPath = Buffer.from(to, 'base64url').toString();
    destDir = path.join(toPath, '.claude', 'agents');
  }
  ensureDir(destDir);
  const content = readFileSafe(srcPath);
  if (!content) return res.status(404).json({ error: 'Source agent not found' });
  fs.writeFileSync(path.join(destDir, agentName + '.md'), content);
  res.json({ ok: true });
});

// SPA fallback
app.get('*', (req, res) => {
  res.sendFile(path.join(staticPath, 'index.html'));
});

const PORT = process.env.PORT || 3847;
app.listen(PORT, () => {
  console.log('');
  console.log('  ╔══════════════════════════════════════╗');
  console.log('  ║         Claude Hub is running         ║');
  console.log(`  ║     http://localhost:${PORT}            ║`);
  console.log('  ╚══════════════════════════════════════╝');
  console.log('');
  console.log(`  Claude dir: ${CLAUDE_DIR}`);
  console.log(`  Config: ${CONFIG_PATH}`);
  console.log('');
});

