import { Link } from 'react-router-dom'
import {
  Bot,
  FolderOpen,
  FileText,
  Terminal,
  ShieldCheck,
  ArrowRight,
  Settings,
} from 'lucide-react'
import type { Project } from '../types'
import { getUnifiedAgents } from '../lib/api'
import { useApi } from '../hooks/useApi'

interface Props {
  projects: Project[]
}

export default function Dashboard({ projects }: Props) {
  const { data: allAgents } = useApi(getUnifiedAgents)

  const totalAgents = allAgents?.length || 0
  const globalAgents = allAgents?.filter((a) => a.scope === 'global').length || 0
  const totalCommands = projects.reduce((sum, p) => sum + p.commands.length, 0)
  const totalRules = projects.reduce((sum, p) => sum + p.rules.length, 0)

  return (
    <div className="p-8 max-w-5xl">
      <h1 className="text-2xl font-semibold tracking-tight mb-6">Dashboard</h1>

      {/* Stats row */}
      <div className="grid grid-cols-4 gap-3 mb-8">
        <StatCard label="Projects" value={projects.length} icon={FolderOpen} color="text-accent" bg="bg-accent-muted" />
        <StatCard label="Agents" value={totalAgents} sub={`${globalAgents} global`} icon={Bot} color="text-purple" bg="bg-purple-muted" />
        <StatCard label="Commands" value={totalCommands} icon={Terminal} color="text-amber" bg="bg-amber-muted" />
        <StatCard label="Rules" value={totalRules} icon={ShieldCheck} color="text-green" bg="bg-green-muted" />
      </div>

      {/* Projects grid */}
      {projects.length === 0 ? (
        <div className="bg-surface rounded-xl border border-border p-12 text-center">
          <FolderOpen className="w-10 h-10 text-text-muted mx-auto mb-3" />
          <p className="text-text-secondary font-medium">No projects found</p>
          <p className="text-text-muted text-sm mt-1 mb-4">
            Add project directories to start managing your Claude configs
          </p>
          <Link
            to="/settings"
            className="inline-flex items-center gap-2 px-4 py-2 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
          >
            <Settings className="w-4 h-4" />
            Open Settings
          </Link>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-3">
          {projects.map((p) => (
            <Link
              key={p.id}
              to={`/projects/${p.id}`}
              className="group bg-surface rounded-xl border border-border p-5 hover:border-accent/30 transition-all"
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-3 min-w-0">
                  <div className="p-2 rounded-lg bg-surface-2 shrink-0">
                    <FolderOpen className="w-4 h-4 text-accent" />
                  </div>
                  <div className="min-w-0">
                    <h3 className="font-semibold text-sm group-hover:text-accent-hover transition-colors truncate">
                      {p.name}
                    </h3>
                    <p className="text-[11px] text-text-muted font-mono truncate">{p.displayPath}</p>
                  </div>
                </div>
                <ArrowRight className="w-4 h-4 text-text-muted opacity-0 group-hover:opacity-100 transition-opacity shrink-0 mt-1" />
              </div>

              <div className="flex items-center gap-2 flex-wrap">
                {p.hasClaudeMd && (
                  <Badge icon={FileText} label="CLAUDE.md" color="text-green" bg="bg-green-muted" />
                )}
                {p.agentCount > 0 && (
                  <Badge icon={Bot} label={`${p.agentCount} agent${p.agentCount !== 1 ? 's' : ''}`} color="text-purple" bg="bg-purple-muted" />
                )}
                {p.commands.length > 0 && (
                  <Badge icon={Terminal} label={`${p.commands.length} cmd${p.commands.length !== 1 ? 's' : ''}`} color="text-amber" bg="bg-amber-muted" />
                )}
                {p.rules.length > 0 && (
                  <Badge icon={ShieldCheck} label={`${p.rules.length} rule${p.rules.length !== 1 ? 's' : ''}`} color="text-text-secondary" bg="bg-surface-2" />
                )}
                {!p.hasClaudeMd && p.agentCount === 0 && p.commands.length === 0 && p.rules.length === 0 && (
                  <span className="text-[11px] text-text-muted">No Claude config</span>
                )}
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  )
}

function StatCard({
  label,
  value,
  sub,
  icon: Icon,
  color,
  bg,
}: {
  label: string
  value: number
  sub?: string
  icon: React.ElementType
  color: string
  bg: string
}) {
  return (
    <div className="bg-surface rounded-xl border border-border p-4">
      <div className="flex items-center justify-between mb-2">
        <p className="text-text-muted text-[11px] font-medium uppercase tracking-wider">{label}</p>
        <div className={`p-1.5 rounded-md ${bg} ${color}`}>
          <Icon className="w-3.5 h-3.5" />
        </div>
      </div>
      <p className="text-2xl font-semibold tracking-tight">{value}</p>
      {sub && <p className="text-[11px] text-text-muted mt-0.5">{sub}</p>}
    </div>
  )
}

function Badge({
  icon: Icon,
  label,
  color,
  bg,
}: {
  icon: React.ElementType
  label: string
  color: string
  bg: string
}) {
  return (
    <span className={`flex items-center gap-1 text-[11px] ${color} ${bg} px-2 py-0.5 rounded-md`}>
      <Icon className="w-3 h-3" />
      {label}
    </span>
  )
}

