import { useState, useEffect } from 'react'
import {
  Trash2,
  Save,
  FolderOpen,
  FolderSearch,
  FileText,
  RotateCcw,
  ChevronDown,
  ChevronRight,
} from 'lucide-react'
import { getConfig, updateProjectDirs, getGlobalClaudeMd, updateGlobalClaudeMd } from '../lib/api'
import { useApi } from '../hooks/useApi'
import DirectoryPicker from '../components/DirectoryPicker'

interface Props {
  onSave: () => void
}

export default function SettingsPage({ onSave }: Props) {
  const { data: config, loading } = useApi(getConfig)
  const { data: claudeMd } = useApi(getGlobalClaudeMd)
  const [dirs, setDirs] = useState<string[]>([])
  const [dirsDirty, setDirsDirty] = useState(false)
  const [savingDirs, setSavingDirs] = useState(false)
  const [pickerOpen, setPickerOpen] = useState(false)

  // CLAUDE.md state
  const [mdContent, setMdContent] = useState('')
  const [mdDirty, setMdDirty] = useState(false)
  const [savingMd, setSavingMd] = useState(false)
  const [mdExpanded, setMdExpanded] = useState(false)

  useEffect(() => {
    if (config) {
      setDirs(config.projectDirs || [])
      setDirsDirty(false)
    }
  }, [config])

  useEffect(() => {
    if (claudeMd) {
      setMdContent(claudeMd.content)
      setMdDirty(false)
    }
  }, [claudeMd])

  const handleAddFromPicker = (dirPath: string) => {
    const display = dirPath.replace(/^\/Users\/[^/]+/, '~')
    if (!dirs.includes(dirPath) && !dirs.includes(display)) {
      setDirs([...dirs, display])
      setDirsDirty(true)
    }
  }

  const handleRemove = (index: number) => {
    setDirs(dirs.filter((_, i) => i !== index))
    setDirsDirty(true)
  }

  const handleSaveDirs = async () => {
    setSavingDirs(true)
    try {
      await updateProjectDirs(dirs)
      setDirsDirty(false)
      onSave()
    } finally {
      setSavingDirs(false)
    }
  }

  const handleSaveMd = async () => {
    setSavingMd(true)
    try {
      await updateGlobalClaudeMd(mdContent)
      setMdDirty(false)
    } finally {
      setSavingMd(false)
    }
  }

  if (loading) {
    return (
      <div className="p-8 flex items-center justify-center h-64">
        <div className="w-6 h-6 border-2 border-accent border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="p-8 max-w-3xl space-y-6">
      <div>
        <h1 className="text-2xl font-semibold tracking-tight">Settings</h1>
        <p className="text-text-secondary text-sm mt-1">Project directories & global config</p>
      </div>

      {/* Project Directories */}
      <div className="bg-surface border border-border rounded-xl p-5">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold">Project Directories</h2>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setPickerOpen(true)}
              className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium bg-accent text-white rounded-lg hover:bg-accent-hover transition-colors"
            >
              <FolderSearch className="w-3.5 h-3.5" />
              Browse
            </button>
            {dirsDirty && (
              <button
                onClick={handleSaveDirs}
                disabled={savingDirs}
                className="flex items-center gap-2 px-3 py-1.5 text-sm font-medium bg-green text-white rounded-lg hover:bg-green/90 transition-colors"
              >
                <Save className="w-3.5 h-3.5" />
                {savingDirs ? 'Saving...' : 'Save'}
              </button>
            )}
          </div>
        </div>

        <p className="text-xs text-text-muted mb-4">
          Parent folders to scan for projects. Finds anything with <code className="text-accent">.claude/</code>, <code className="text-accent">CLAUDE.md</code>, or <code className="text-accent">package.json</code>.
        </p>

        {dirs.length === 0 ? (
          <div className="py-6 text-center border border-dashed border-border rounded-lg">
            <FolderOpen className="w-8 h-8 text-text-muted mx-auto mb-2" />
            <p className="text-text-muted text-sm">Click "Browse" to add project folders</p>
          </div>
        ) : (
          <div className="space-y-1.5">
            {dirs.map((dir, i) => (
              <div key={i} className="flex items-center justify-between bg-surface-2 rounded-lg px-4 py-2.5 group">
                <span className="text-sm font-mono text-text-secondary truncate">{dir}</span>
                <button
                  onClick={() => handleRemove(i)}
                  className="p-1 rounded-md text-text-muted hover:text-red hover:bg-red-muted transition-colors opacity-0 group-hover:opacity-100"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Global CLAUDE.md */}
      <div className="bg-surface border border-border rounded-xl">
        <button
          onClick={() => setMdExpanded(!mdExpanded)}
          className="w-full flex items-center justify-between p-5 text-left"
        >
          <div className="flex items-center gap-3">
            <FileText className="w-5 h-5 text-accent" />
            <div>
              <h2 className="text-base font-semibold">Global CLAUDE.md</h2>
              <p className="text-xs text-text-muted mt-0.5">Instructions applied to Claude across all projects</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {claudeMd?.exists && (
              <span className="text-[10px] bg-green-muted text-green px-2 py-0.5 rounded-md">Active</span>
            )}
            {mdExpanded ? <ChevronDown className="w-4 h-4 text-text-muted" /> : <ChevronRight className="w-4 h-4 text-text-muted" />}
          </div>
        </button>

        {mdExpanded && (
          <div className="border-t border-border p-5">
            <div className="flex items-center justify-end gap-2 mb-3">
              {mdDirty && (
                <button
                  onClick={() => { if (claudeMd) setMdContent(claudeMd.content); setMdDirty(false) }}
                  className="flex items-center gap-1.5 px-3 py-1.5 text-xs text-text-secondary hover:text-text rounded-lg hover:bg-surface-2 transition-colors"
                >
                  <RotateCcw className="w-3 h-3" /> Reset
                </button>
              )}
              <button
                onClick={handleSaveMd}
                disabled={!mdDirty || savingMd}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium bg-accent text-white rounded-lg hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
              >
                <Save className="w-3 h-3" /> {savingMd ? 'Saving...' : 'Save'}
              </button>
            </div>
            <textarea
              value={mdContent}
              onChange={(e) => { setMdContent(e.target.value); setMdDirty(true) }}
              className="w-full h-80 bg-bg border border-border rounded-lg p-4 font-mono text-sm text-text resize-y focus:outline-none focus:border-accent/50 transition-colors"
              spellCheck={false}
              placeholder="# Global instructions for Claude&#10;&#10;These apply across ALL your projects..."
            />
          </div>
        )}
      </div>

      {/* System Info */}
      <div className="bg-surface border border-border rounded-xl p-5">
        <h2 className="text-base font-semibold mb-3">System</h2>
        <div className="space-y-2 text-sm">
          <div className="flex items-center justify-between">
            <span className="text-text-secondary">Claude directory</span>
            <span className="font-mono text-xs text-text-muted">{config?.claudeDir}</span>
          </div>
          <div className="flex items-center justify-between">
            <span className="text-text-secondary">Status</span>
            <span className={`text-xs px-2 py-0.5 rounded-md ${config?.claudeDirExists ? 'bg-green-muted text-green' : 'bg-red-muted text-red'}`}>
              {config?.claudeDirExists ? 'Connected' : 'Not found'}
            </span>
          </div>
        </div>
      </div>

      <DirectoryPicker
        open={pickerOpen}
        onClose={() => setPickerOpen(false)}
        onSelect={handleAddFromPicker}
        existingDirs={dirs}
      />
    </div>
  )
}

